---开启购买页面
---@param itemData    table 物品数据
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreMgr:OpenBuyItemDialog(itemData, storeType ,isCloseSDKSecondConfirm)
    local isLocked = OverseaStoreUtils.ProductIsLocked(itemData)
    if isLocked then
        GameUtils.Toast(localize("商品未解锁"))
        return
    end

    if checkInt(itemData.isFree) == 1 then
        if OverseaStoreUtils.ProductIsSoldOut(itemData) then
            GameUtils.Toast(localize("商品已售罄"))
        else
            -- 免费商品直接请求
            self:FreeBuyRequest(storeType, itemData)
        end
        return
    end
    
    local goodsVo = nil
    local goodsType = GoodsUtils.GetIdType(itemData.icon)
    if goodsType == Constants.IDType.GoodsGift then
        goodsVo = itemData
    end

    local payPoint = isNotNull(itemData.price) and itemData.price or itemData.payPoint
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = itemData.icon,
        goodsNum       = itemData.num,
        prices         = itemData.prices,
        coinPrices     = itemData.coinPrices,
        maxBuyNum      = itemData.currentStock,
        rewards        = itemData.rewards,
        remainTime     = itemData.refreshTime,
        endTime        = itemData.endTime,
        refreshType    = itemData.refreshType, 
        goodsVo        = goodsVo,
        payPoint       =  payPoint,
        isCloseSDKSecondConfirm = isCloseSDKSecondConfirm,
        buyCb          = function (price, buyNum)
        
            if isNotNull(payPoint) then 
                self:SDKBuyRequest(itemData)
            else
                self:BuyRequest(storeType, itemData.productId, buyNum, price)
            end
        end
    }})
end

---免费礼包请求
---@param storeType   OverseaStoreConstants.StoreType
---@param itemData    table 物品数据
function OverseaStoreMgr:FreeBuyRequest(storeType, itemData)
    local data = {
        productId    = itemData.productId,
        activityUuid = itemData.activityUuid,
    }
    GameUtils.Request(Interfaces.OverseaStoreFreeDraw, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        GoodsUtils.DrawRewards(responseData.rewards, true)

                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                        self:RefreshStock(storeType, checkInt(itemData.productId), 1)

                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store free chest buy" .. errStr)
            end
    )
end

---SDK购买请求
---@param itemData    table 物品数据
function OverseaStoreMgr:SDKBuyRequest(itemData)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(itemData.icon)
    local description = nil
    if goodsVo then
        description  = goodsVo.name
    else
        description = localize("礼包")
    end
    local payPoint = isNotNull(itemData.price) and itemData.price or itemData.payPoint
    SDKService:GetInstance():PayMoney({
        productId = itemData.productId,
        channelProductId = itemData.channelProductId,
        productDesc = description,
        payAmount = checkNumber(payPoint),
        data = itemData
    })
end

---购买请求
---@param storeType   OverseaStoreConstants.StoreType
---@param productId   integer  商品id
---@param buyNum      integer  购买数量
---@param price       table    currency:货币id, current:单价（Coin类型为消耗的道具列表）
---@param callback    function 结束回调
function OverseaStoreMgr:BuyRequest(storeType, productId, buyNum, price, callback)
    local requestPath = Interfaces.GroceryCommonBuy
    if storeType == OverseaStoreConstants.StoreType.SkinBundle then
        requestPath = Interfaces.StoreSkinBundleBuy
    elseif storeType == OverseaStoreConstants.StoreType.SkinScene then
        requestPath = Interfaces.StoreSkinSceneBuy
    end

    local data = {
        productId = productId,
        num       = buyNum,
        currency  = price.currency
    }

    GameUtils.Request(requestPath, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        ---这里只有Interfaces.GroceryCommonBuy 才会返回consume 所以要区分一下
                        if isSet(responseData, "consume") and table.count(responseData.consume) > 0 then
                            GoodsUtils.ConsumeGoods(responseData.consume, true)
                        else
                            local consume = {}
                            table.insert(consume, { ["num"] = -price.current * buyNum;
                                                    ["goodsId"] = price.currency, ['productId'] = productId })
                            GoodsUtils.DrawRewards(consume, true)
                        end
                       
                        GoodsUtils.DrawRewards(responseData.rewards, true)
                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)

                        if next(checkTable(responseData.nextChest)) ~= nil then
                            --StoreUtils.RefreshNextChest(storeType, productId, responseData.nextChest)
                        else
                            self:RefreshStock(storeType, checkInt(productId), checkInt(buyNum))
                        end

                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        if callback ~= nil then
                            callback()
                        end
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store buy" .. errStr)
            end
    )
end

---刷新库存
---@param storeType   OverseaStoreConstants.StoreType
---@param productId   integer 商品id
---@param buyNum      integer 购买数量
function OverseaStoreMgr:RefreshStock(storeType, productId, buyNum)
    local comp = self:GetStoreComponent()
    comp:ReduceStock(storeType, productId, buyNum)
    Events.Broadcast(Constants.EventNames.OVERSEA_STORE_REFRESH, storeType, productId, buyNum)
end

---开启定时器
function OverseaStoreMgr:StartTimer()
    self._deltaTime = 0
    if not self._updateHandler then
        self._updateHandler = Bind(self,self.OnUpdate)
        MonoHelper.AddUpdateListener(self._updateHandler)
    end
end

---重置定时器
function OverseaStoreMgr:ResetTimer()
    self._deltaTime = 0
end

---停止定时器
function OverseaStoreMgr:StopTimer()
    self._deltaTime = 0
    MonoHelper.RemoveUpdateListener(self._updateHandler)
    self._updateHandler = nil
end

---定时器更新
function OverseaStoreMgr:OnUpdate()
    self._deltaTime = self._deltaTime + CS.UnityEngine.Time.deltaTime
    if self._deltaTime >= CountTime then
        self._deltaTime = self._deltaTime - CountTime

        local comp = self:GetStoreComponent()
        if comp then
            comp:DecreaseTime(CountTime)
        end
    end
end

---检查商城new状态 
---@param storeType   OverseaStoreConstants.StoreType
function OverseaStoreMgr:CheckNewSymbolState(storeType)
    if storeType == OverseaStoreConstants.StoreType.TimeLimit then
        local data = self:GetTimeLimitActivityData().products
        for i, v in ipairs(checkTable(data)) do
            if self:CheckTimeLimitGiftNew(v) then
                return true
            end
        end
        return false
    else
        -- 检查页签是否存在子页签
        local config = OverseaStoreConstants.StorePanelConfigs[storeType]
        if config and config.sub then
            for i, v in ipairs(config.sub) do
                if self:IsNewStore(v.type) then
                    return true
                end
            end
            return false
        else
            return self:IsNewStore(storeType)
        end
    end
end

---检查限时礼包new状态
function OverseaStoreMgr:CheckTimeLimitGiftNew(data)
    if checkInt(data.startTime) > 0 and checkInt(data.isFree) == 0 then
        local key = CfUtils.GetLocalData(self:GetTimeLimitGiftNewSymbolKey(data), '0')
        return checkInt(key) == 0
    else
        return false
    end
end

---获取限时礼包new标识key
function OverseaStoreMgr:GetTimeLimitGiftNewSymbolKey(data)
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComp.playerDojo.playerId
    return string.format('TimeLimitNew%d%d%d', checkInt(playerId), checkInt(data.startTime), checkInt(data.productId))
end

