function OverseaStoreMgr:RefreshRenovateHaveRedPoint(data)
    local ids = self:GetRenovateShopRedPointIds()
    local isHave = false
    if table.count(ids) > 0 then
        if not isNull(data) and next(data) and table.count(data.products) > 0 then
            local index = 0
            for i = 1, table.count(data.products) do
                for j = table.count(ids), 1, -1 do
                    if tonumber(ids[j]) == data.products[i].productId then
                        index = index + 1
                    end
                end
            end

            if index ~= table.count(data.products) then
                isHave = true
            end
        end
    else
        if not isNull(data) and next(data) and table.count(data.products) > 0 then
           isHave = true
        end
    end

    GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaStoreRenovate, isHave and 1 or 0)
end

function OverseaStoreMgr:GetRenovateShopRedPointIds()
    local str = CfUtils.GetLocalData("OverseaStoreMgrRenovateShopIds", "")
    return  checkTable(CfUtils.Split(str, ","))
end

function OverseaStoreMgr:RemoveRenovateShopRedPointId(id)
    local ids = self:GetRenovateShopRedPointIds()
    for i = table.count(ids), 1, -1 do
        if checkNumber(id) == checkNumber(ids[i]) then
            table.remove(ids, i)
        end
    end
    self:SaveRenovateShopRedPointData(ids)
end

function OverseaStoreMgr:AddRenovateShopRedPointId(id)
    local ids = self:GetRenovateShopRedPointIds()
    local isFind = false
    for i, v in pairs(ids) do
        if checkNumber(v) == id then
            isFind = true
        end
    end

    if not isFind then
        table.insert(ids,id)
        self:SaveRenovateShopRedPointData(ids)
    end
end

function OverseaStoreMgr:SaveRenovateShopRedPointData(data)
    local str = ""
    for k, v in pairs(checkTable(data)) do
        if k == 1 then
            str = v
        else
            str = str..","..v
        end
    end
    CfUtils.WriteLocalData("OverseaStoreMgrRenovateShopIds", str)
end

---解锁新商城
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreMgr:UnlockNewStore(storeType)
    self._newStoreData[storeType] = {} 
end

---解锁新商品
---@param storeType OverseaStoreConstants.StoreType
---@param products table 商品数据
function OverseaStoreMgr:UnlockNewProduct(storeType, products)
    if self._newStoreData[storeType] then
        table.merge(self._newStoreData[storeType], products)
    else
        self._newStoreData[storeType] = checkTable(products)
    end
end

---判断是否是新商城
function OverseaStoreMgr:IsNewStore(storeType)
    return self._newStoreData[storeType] and true or false
end

---判断是否是新商品
function OverseaStoreMgr:IsNewStoreProduct(storeType, productId)
    if self._newStoreData[storeType] then
        if productId == nil then
            return true
        end
        return self._newStoreData[storeType][tostring(productId)] and true or false
    end
    return false
end

---记录选中的商城
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreMgr:RecordSelectedStore(storeType)
    self._selectedStore[storeType] = true
end

---清除新商城
function OverseaStoreMgr:ClearNewStore()
    for k, v in pairs(self._selectedStore) do
        if self._newStoreData[k] then
            self._newStoreData[k] = nil
        end
    end
    
    self._selectedStore = {}
end

---是否存在新商城
function OverseaStoreMgr:CheckNewStore()
    return next(self._newStoreData) ~= nil
end

