function OverseaStoreMgr:SetOptionalGiftChoiceId(productId, choiceId)
    local data = self:GetOptionalGiftData()
    for _, v in ipairs(checkTable(data.products)) do
        if checkInt(v.productId) == productId then
            v.choiceRewardsId = choiceId
