        end
    end
end

---自选礼包购买
function OverseaStoreMgr:OptionalGiftBuy(data, cb)
    local isFree = OverseaStoreUtils.ProductIsFree(data)
    if isFree then
        GameUtils.Request(Interfaces.StoreOptionalGiftBuy, {productId = data.productId}, function (request, response)
            if checkNumber(response.errCode) == 0 then
                local responseData = checkTable(response.data)
                if #responseData.rewards > 0 then
                    GoodsUtils.DrawRewards(responseData.rewards, true)

                    CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                    self:RefreshStock(OverseaStoreConstants.StoreType.OptionalGift, checkInt(data.productId), 1)

                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                    Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
                    if cb then
                        cb()
                    end
                end
            end
        end)
    else
        local t = clone(data.rewards)
        local choice = string.split(data.choiceRewardsId, ',')
        for i = 1, 3 do
            local rewardGroup = checkTable(data['rewardGroup' .. i])
            local choiceId = checkNumber(choice[i])
            if choiceId ~= 0 then
                table.insert(t, {
                    goodsId = rewardGroup[choiceId].goodsId,
                    num = rewardGroup[choiceId].num
                })
                
            end
        end

        local OKAction = function()
            if isNotNull(data.payPoint) then
                if cb then
                    cb()
                end
                self:SDKBuyRequest(data)
            elseif isNotNull(data.prices) then
                local consume = clone(data.prices)
                for _, v in pairs(consume) do
                    v.goodsId = v.currency
                    v.num = v.current
                    v.productId = checkNumber(data.productId)
                end
    
                local _, errTip = GoodsUtils.CheckGoodConsume(consume)
                if errTip then
                    if consume[1].goodsId == Constants.Currency.PayDiamondId then
                        local productVo = GoodsConfMgr:GetGoodsVoById(consume[1].goodsId)
                        ServerDifferenceMgr:WrapPrimaryCurrencyBuy({currency = consume[1].goodsId,current = consume[1].num, productName = productVo.name})
                    else
                        GameUtils.Toast(errTip)
                    end
                    return
                end
    
                GameUtils.Request(Interfaces.StoreOptionalGiftBuy, {productId = data.productId, currency = consume[1].goodsId}, function (request, response)
                    if checkNumber(response.errCode) == 0 then
                        local responseData = checkTable(response.data)
                        if #responseData.rewards > 0 then
                            GoodsUtils.ConsumeGoods(consume, true)
                            
                            GoodsUtils.DrawRewards(responseData.rewards, true)
    
                            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                            self:RefreshStock(OverseaStoreConstants.StoreType.OptionalGift, checkInt(data.productId), 1)
    
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
                            if cb then
                                cb()
                            end
                        end
                    end
                end)
                
            end
        end
        
        local GetText = function ()
            if isNotNull(data.payPoint) then
                return localize("确认花费_num_购买礼包？", {_num_ = data.payPoint})    
            end

            if isNotNull(data.prices) then
                local consume = data.prices
                local consumeData = consume[1]
                -- print(table.toString(consumeData))
                local goodsId = consumeData.currency
                local productVo = GoodsConfMgr:GetGoodsVoById(goodsId)
                return localize("确认花费_num__name_购买礼包？", {_num_ = consumeData.current, _name_ = productVo.name})
            end
            
        end

        GameUtils.SecondConfirm(GetText(), OKAction, nil, nil, 6, t)


        
    end
end

